changeSet.sql:
DO $heal$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE n.nspname = 'nexus' AND c.relname = 'idx_ta_tenant_source_collection_id' AND NOT i.indisvalid) THEN
        PERFORM set_config('lock_timeout', '5s', true);
        DROP INDEX nexus.idx_ta_tenant_source_collection_id;
    END IF;
END
$heal$;

SET lock_timeout = '30s';
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_ta_tenant_source_collection_id
    ON nexus.topic_assignments (tenant_id, source_collection_id);
RESET lock_timeout;

